PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', avatar BLOB, created INTEGER NOT NULL, seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS saves(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, payload TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS friends(sender INTEGER REFERENCES users(id) ON DELETE CASCADE, recipient INTEGER REFERENCES users(id) ON DELETE CASCADE, accepted INTEGER NOT NULL DEFAULT 0 CHECK(accepted IN(0,1)), PRIMARY KEY(sender,recipient), CHECK(sender<>recipient));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 500), created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY, host INTEGER REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity BETWEEN 2 AND 4), topic TEXT NOT NULL, duration INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'waiting', round INTEGER NOT NULL DEFAULT 0, deadline INTEGER NOT NULL DEFAULT 0, deck TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS players(room_id INTEGER REFERENCES rooms(id) ON DELETE CASCADE, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, score INTEGER NOT NULL DEFAULT 0, hint_round INTEGER, hint_option INTEGER, PRIMARY KEY(room_id,user_id));
CREATE TABLE IF NOT EXISTS answers(room_id INTEGER, user_id INTEGER, round INTEGER NOT NULL, choice INTEGER NOT NULL, correct INTEGER NOT NULL, PRIMARY KEY(room_id,user_id,round), FOREIGN KEY(room_id,user_id) REFERENCES players(room_id,user_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires);
CREATE INDEX IF NOT EXISTS messages_time ON messages(created);
CREATE INDEX IF NOT EXISTS players_user ON players(user_id);
